from typing import Optional, Tuple
import math

def find_cube_difference_pair(n: int) -> Optional[Tuple[int, int]]:
    d = 1
    while d * d * d <= n:
        if n % d == 0:
            m = n // d
            q = 4 * m - d * d
            if q > 0 and q % 3 == 0:
                s2 = q // 3
                s = math.isqrt(s2)
                if s * s == s2:
                    if (s - d) % 2 == 0:
                        y = (s - d) // 2
                        if y > 0:
                            x = y + d
                            return (x, y)
        d += 1
    return None

